#include <iostream>
#include <vector>
#include <queue>
#include <complex>
#include <ctime>
#include <chrono>
#include <iomanip>
#include <cassert>
#include <algorithm>
#include <climits>
#include <cmath>

using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef pair<ld,ld> pdd;
typedef complex<ld> pt;
typedef vector<pt> pol;
typedef vector<int> vi;

const char NEWLINE = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1000000007LL;
const ld EPS = 1e-10;
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

const int MAX_TIME = 99;
const int MAX_C = 12;

struct Edge {
    int to, reverse;
    ll flow, capacity, cost;
};

vector<Edge> graph[5000];
int degree[5000];
ll minCostAccumulated;

void initializeGraph(int n) {
    minCostAccumulated = 0;
    for (int i = 0; i < n; ++i) {
        degree[i] = 0;
        graph[i].clear();
    }
}

void addConnection(int u, int v, ll cap = 1, ll cost = 0) {
    minCostAccumulated = max(minCostAccumulated, cap);
    graph[u].push_back({v, degree[v]++, 0, cap, cost});
    graph[v].push_back({u, degree[u]++, 0, 0, -cost});
}

bool visitedNodes[5000];
int parentNodes[5000];
ll potential[5000], distances[5000];

void initializePotential(int n) {
    fill(potential, potential + n, 0);
    for (int step = 1; step < n; ++step) {
        for (int node = 0; node < n; ++node) {
            for (const Edge& e : graph[node]) {
                if (e.capacity) {
                    potential[e.to] = min(potential[e.to], potential[node] + e.cost);
                }
            }
        }
    }
}

ll augmentPath(int source, int sink, ll& totalCost, int nodeCount, bool useQueue) {
    fill(visitedNodes, visitedNodes + nodeCount, false);
    fill(distances, distances + nodeCount, INF);
    distances[source] = 0;

    if (useQueue) {
        queue<int> q;
        q.push(source);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (visitedNodes[u]) continue;
            visitedNodes[u] = true;
            for (const Edge& e : graph[u]) {
                if (e.flow < e.capacity && distances[e.to] > distances[u] + potential[u] - potential[e.to] + e.cost) {
                    distances[e.to] = distances[u] + potential[u] - potential[e.to] + e.cost;
                    parentNodes[e.to] = e.reverse;
                    q.push(e.to);
                }
            }
        }
    } else {
        for (int u = source; u != -1; ) {
            visitedNodes[u] = true;
            for (const Edge& e : graph[u]) {
                if (e.flow < e.capacity && distances[e.to] > distances[u] + potential[u] - potential[e.to] + e.cost) {
                    distances[e.to] = distances[u] + potential[u] - potential[e.to] + e.cost;
                    parentNodes[e.to] = e.reverse;
                }
            }
            u = -1;
            ll best = INF;
            for (int i = 0; i < nodeCount; ++i) {
                if (!visitedNodes[i] && distances[i] < best) {
                    best = distances[u = i];
                }
            }
        }
    }

    if (distances[sink] >= INF) return 0;

    ll bottleneck = INF;
    for (int node = sink; node != source; ) {
        const Edge& revEdge = graph[node][parentNodes[node]];
        bottleneck = min(bottleneck, graph[revEdge.to][revEdge.reverse].capacity - graph[revEdge.to][revEdge.reverse].flow);
        node = revEdge.to;
    }

    for (int node = sink; node != source; ) {
        Edge& revEdge = graph[node][parentNodes[node]];
        Edge& forwardEdge = graph[revEdge.to][revEdge.reverse];
        forwardEdge.flow += bottleneck;
        revEdge.flow -= bottleneck;
        totalCost += bottleneck * forwardEdge.cost;
        node = revEdge.to;
    }

    for (int i = 0; i < nodeCount; ++i) {
        potential[i] = min(INF, distances[i] + potential[i]);
    }
    return bottleneck;
}

ll computeMinCostMaxFlow(int source, int sink, ll& totalCost, int nodeCount, bool useQueue) {
    initializePotential(nodeCount);
    ll totalFlow = 0;
    totalCost = 0;
    while (ll df = augmentPath(source, sink, totalCost, nodeCount, useQueue)) {
        totalFlow += df;
    }
    return totalFlow;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int sourceNode = 0;
    const int sinkNode = n * MAX_TIME + 1;

    for (int i = 0; i < k; ++i) {
        int a;
        cin >> a;
        addConnection(sourceNode, a, 1, 0);
    }

    for (int t = 0; t < MAX_TIME; ++t) {
        addConnection(1 + t * n, sinkNode, INF, 0);
        if (t > 0) {
            for (int i = 1; i <= n; ++i) {
                addConnection(i + (t - 1) * n, i + t * n, INF, c);
            }
        }
    }

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < MAX_C; ++j) {
            int cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < MAX_TIME; ++t) {
                addConnection(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                addConnection(b + (t - 1) * n, a + t * n, 1, cost * d + c);
            }
        }
    }

    ll totalCost, flow = computeMinCostMaxFlow(sourceNode, sinkNode, totalCost, sinkNode + 1, true);
    assert(flow == k);
    cout << totalCost << NEWLINE;

    return 0;
}
